```go
package main

import "fmt"

type Notifier interface {
    Notify(string) error
}

type Console struct{}

func (Console) Notify(message string) error {
    fmt.Println(message)
    return nil
}

func Alert(n Notifier, message string) error {
    return n.Notify(message)
}

func main() {
    _ = Alert(Console{}, "build complete")
}
```
`Alert` needs only `Notify`. `Console` satisfies that contract without declaring an `implements` relationship.

```go
package main

import "fmt"

type User struct{ Name string }

type UserFinder interface {
    Find(int) (User, error)
}

type MemoryUsers map[int]User

func (m MemoryUsers) Find(id int) (User, error) { return m[id], nil }

func Greeting(users UserFinder, id int) string {
    user, _ := users.Find(id)
    return "Hello, " + user.Name
}

func main() {
    fmt.Println(Greeting(MemoryUsers{7: {Name: "Mina"}}, 7))
}
```
`Greeting` owns the one-method view it needs. `MemoryUsers` can have other operations without widening that dependency.

```go
package main

import "fmt"

func describe(value any) string {
    switch value := value.(type) {
    case int:
        return fmt.Sprintf("integer %d", value)
    case string:
        return "text " + value
    default:
        return fmt.Sprintf("other %T", value)
    }
}

func main() {
    fmt.Println(describe(7))
    fmt.Println(describe("go"))
}
```
The type switch safely narrows the dynamic value. A more specific input type would be better if only integers or only strings were valid.
